# Tienda Aurora

Online store for handmade candles. Express API on Node 22, PostgreSQL 16 (docker compose up db), transactional email through Resend. Customer-facing copy is in Spanish (es-CO).
CREATE TABLE users (id serial PRIMARY KEY, email text NOT NULL UNIQUE, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE orders (id serial PRIMARY KEY, user_id integer NOT NULL REFERENCES users (id), cents integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
exports.charge = async (gateway, order) => gateway.charge({ amount: order.cents, customer: order.customerId });
const { pool } = require('../db.js');
exports.findByEmail = async (email) => (await pool.query('SELECT * FROM users WHERE email = $1', [email])).rows[0];
const express = require('express');
const { pool } = require('./db.js');
const app = express();
app.use(express.json());
app.get('/api/orders', async (req, res) => {
  const { rows } = await pool.query('SELECT id, cents, created_at FROM orders WHERE user_id = $1', [req.userId]);
  res.json(rows);
});
module.exports = app;
const { Pool } = require('pg');
exports.pool = new Pool({ connectionString: process.env.DATABASE_URL });
{
  "name": "tienda-aurora",
  "version": "1.0.0",
  "private": true,
  "scripts": { "test": "node --test" },
  "dependencies": { "express": "^4.19.2", "pg": "^8.11.5", "resend": "^3.2.0" }
}

